package glitch

import data.glitch_lib

# Insecure boolean values for string-based bools (yes/no)
insecure_bool_strings := {"no", "false", "off", "0", "disable", "disabled"}

# Insecure protocol schemes
insecure_protocols := {"http", "ftp", "smtp", "ldap", "telnet", "pop3", "imap"}

# Insecure SSL/TLS modes
insecure_ssl_modes := {"DISABLED", "ALLOW", "PREFERRED"}

# Insecure TLS versions
insecure_tls_versions := {"TLS1_0", "TLS1_1", "SSL", "SSLv2", "SSLv3", "TLS1.0", "TLS1.1", "1.0", "1.1"}

# Attributes that indicate disabled certificate/TLS validation
cert_validation_attrs := {
    "validate_certs", "verify_ssl", "verify", "ssl_verify", "verify_certs",
    "verify_server_certificate", "verify_ca", "verify_certificate", "ssl_verify_peer",
    "insecure_skip_verify", "skip_verify", "disable_certificate_validation"
}

# Attributes for security protocols
security_protocol_attrs := {
    "protocol", "scheme", "listener_protocol", "frontend_protocol", 
    "backend_protocol", "target_protocol", "upstream_protocol",
    "transfer_protocol", "access_protocol", "mount_protocol",
    "security_protocol", "auth_protocol"
}

# Attributes for TLS/SSL configuration
ssl_config_attrs := {
    "ssl_mode", "ssl_policy", "tls_policy", "encryption_policy",
    "min_tls_version", "tls_version", "ssl_version", "minimum_protocol",
    "cipher_suites", "sasl_mechanism"
}

# Attributes for URLs, connection strings, sources
url_attrs := {
    "url", "source", "src", "connection_string", "endpoint", "broker_url", 
    "database_url", "connection_uri", "jdbc_url", "redis_url", 
    "registry_endpoint", "backend_address", "state_endpoint", "remote_state",
    "download_url", "base_url", "server_url", "api_url", "grafana_url",
    "image", "repository", "registry"
}

# Check if value starts with insecure URL scheme by walking expression tree
expr_has_insecure_url(expr) {
    expr.ir_type == "String"
    str := lower(expr.value)
    startswith(str, "http://")
} else {
    expr.ir_type == "String"
    str := lower(expr.value)
    startswith(str, "ftp://")
} else {
    expr.ir_type == "Sum"
    expr_has_insecure_url(expr.left)
} else {
    expr.ir_type == "Sum"
    expr_has_insecure_url(expr.right)
}

# Check if string value is insecure boolean string
is_insecure_bool_string(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    insecure_bool_strings[lower_val]
}

# Check if attribute indicates disabled certificate validation
is_disabled_cert_validation(attr_name, value) {
    cert_validation_attrs[attr_name]
    value.ir_type == "Boolean"
    value.value == false
} else {
    cert_validation_attrs[attr_name]
    value.ir_type == "String"
    is_insecure_bool_string(value)
}

# Check if value is insecure protocol
is_insecure_protocol(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    insecure_protocols[lower_val]
}

# Check if value is insecure TLS version
is_insecure_tls_version(value) {
    value.ir_type == "String"
    upper_val := upper(value.value)
    insecure_tls_versions[upper_val]
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    startswith(lower_val, "tls1.0")
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    startswith(lower_val, "tls1.1")
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    startswith(lower_val, "ssl")
}

# Check if value is insecure SSL mode
is_insecure_ssl_mode(value) {
    value.ir_type == "String"
    upper_val := upper(value.value)
    insecure_ssl_modes[upper_val]
}

# Walk any expression type to find insecure URLs
find_insecure_url_in_expr(expr) {
    expr.ir_type == "String"
    expr_has_insecure_url(expr)
} else {
    expr.ir_type == "Sum"
    expr_has_insecure_url(expr)
} else {
    expr.ir_type == "Hash"
    some val in expr.value
    find_insecure_url_in_expr(val.value)
} else {
    expr.ir_type == "Array"
    some elem in expr.value
    find_insecure_url_in_expr(elem)
}

# Rule: Disabled certificate validation (handles "validate_certs: no")
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_disabled_cert_validation(attr.name, attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Certificate validation disabled. (CWE-319)"
    }
}

# Rule: Disabled certificate validation in variables
Glitch_Analysis[result] {
