    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    node := vars[_]

    is_disabled_cert_validation(node.name, node.value)

    result := {
        "type": "sec_https",
        "element": node,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Certificate validation disabled in variable. (CWE-319)"
    }
}

